import CryptoKit
import Foundation
import Testing

@testable import IsudoKit

/// Checks this implementation against vectors generated by the Rust
/// reference (`crates/phone/examples/vectors.rs`).
struct Vectors {
    let root: [String: Any]

    init() throws {
        let file = URL(filePath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent().deletingLastPathComponent()
            .appending(path: "testdata/vectors.json")
        root = try #require(try JSONSerialization.jsonObject(with: Data(contentsOf: file)) as? [String: Any])
    }

    func section(_ name: String) throws -> [String: Any] {
        try #require(root[name] as? [String: Any], "missing section \(name)")
    }

    func string(_ section: String, _ key: String) throws -> String {
        try #require(try self.section(section)[key] as? String, "missing \(section).\(key)")
    }

    func hex(_ section: String, _ key: String) throws -> Data {
        try Codec.hexDecode(try string(section, key))
    }

    func b64(_ section: String, _ key: String) throws -> Data {
        try Codec.b64Decode(try string(section, key))
    }
}

@Suite struct VectorTests {
    let vectors: Vectors

    init() throws {
        vectors = try Vectors()
    }

    @Test func codec() throws {
        let section = try vectors.section("codec")
        for pair in try #require(section["b64"] as? [[String]]) {
            let bytes = try Codec.hexDecode(pair[0])
            #expect(Codec.b64Encode(bytes) == pair[1])
            #expect(try Codec.b64Decode(pair[1]) == bytes)
            #expect(Codec.hexEncode(bytes) == pair[0])
        }
        for invalid in try #require(section["b64_invalid"] as? [String]) {
            #expect(throws: Codec.DecodeError.self, "accepted \(invalid)") { try Codec.b64Decode(invalid) }
        }
        #expect(throws: Codec.DecodeError.self) { try Codec.hexDecode("abc") }
        #expect(throws: Codec.DecodeError.self) { try Codec.hexDecode("zz") }
        #expect(try Codec.hexDecode("009AfF") == Data([0x00, 0x9a, 0xff]))
        // Round trip at every length.
        let data = Data((0..<200).map { UInt8(truncatingIfNeeded: $0 &* 37) })
        for length in 0..<data.count {
            #expect(try Codec.b64Decode(Codec.b64Encode(data.prefix(length))) == data.prefix(length))
        }
    }

    @Test func requestDecodesToTheSameFields() throws {
        let bytes = try vectors.hex("request", "bytes_hex")
        let request = try Request.decode(bytes)
        let fields = try #require(try vectors.section("request")["fields"] as? [String: Any])
        func hex(_ key: String) throws -> Data { try Codec.hexDecode(try #require(fields[key] as? String)) }
        func number(_ key: String) throws -> UInt64 { try #require(fields[key] as? NSNumber).uint64Value }

        #expect(request.nonce == (try hex("nonce_hex")))
        #expect(request.pairingID == (try hex("pairing_id_hex")))
        #expect(request.issuedAt == (try number("issued_at")))
        #expect(UInt64(request.ttlSecs) == (try number("ttl_secs")))
        #expect(UInt64(request.uid) == (try number("uid")))
        #expect(UInt64(request.gid) == (try number("gid")))
        #expect(request.user == (try hex("user_hex")))
        #expect(request.host == (try hex("host_hex")))
        #expect(request.cwd == (try hex("cwd_hex")))
        #expect(request.exe == (try hex("exe_hex")))
        #expect(UInt64(request.flags) == (try number("flags")))
        #expect(UInt64(request.stdin.rawValue) == (try number("stdin")))
        let argv = try #require(fields["argv_hex"] as? [String]).map { try Codec.hexDecode($0) }
        #expect(request.argv == argv)
        let env = try #require(fields["env"] as? [[String: Any]])
        #expect(request.env.count == env.count)
        for (decoded, expected) in zip(request.env, env) {
            #expect(UInt64(decoded.origin.rawValue) == (expected["origin"] as? NSNumber)?.uint64Value)
            #expect(Codec.hexEncode(decoded.name) == expected["name_hex"] as? String)
            #expect(Codec.hexEncode(decoded.value) == expected["value_hex"] as? String)
        }
        // The sample carries a variable built by isudo itself, first.
        #expect(request.env.first?.origin == .constructed)
        #expect(RequestDisplay(request).callouts.count(where: { if case .riskyVariable = $0.kind { true } else { false } }) == 1)
        let ancestry = try #require(fields["ancestry"] as? [[String: Any]])
        #expect(request.ancestry.count == ancestry.count)
        for (decoded, expected) in zip(request.ancestry, ancestry) {
            #expect(UInt64(decoded.pid) == (expected["pid"] as? NSNumber)?.uint64Value)
            #expect(Codec.hexEncode(decoded.name) == expected["name_hex"] as? String)
        }

        // Our encoder, used only for fixtures, agrees with the reference.
        #expect(request.encode() == bytes)
        #expect(Messages.requestDigest(bytes) == (try vectors.hex("request", "digest_hex")))
        #expect(Messages.requestID(bytes) == (try vectors.hex("request", "request_id_hex")))
    }

    @Test func requestDecodingIsStrict() throws {
        let invalid = try #require(try vectors.section("request")["invalid_bytes_hex"] as? [String: String])
        #expect(invalid.count == 3)
        for (name, hex) in invalid {
            #expect(throws: WireError.self, "accepted \(name)") { try Request.decode(try Codec.hexDecode(hex)) }
        }
        // Every proper prefix is rejected.
        let bytes = try vectors.hex("request", "bytes_hex")
        for length in 0..<bytes.count {
            #expect(throws: WireError.self) { try Request.decode(bytes.prefix(length)) }
        }
        // A length claim larger than the input is caught before copying.
        var huge = bytes
        let userLengthAt = 8 + 32 + 16 + 8 + 4 + 4 + 4
        huge.replaceSubrange(userLengthAt..<userLengthAt + 4, with: [0xff, 0xff, 0xff, 0xff])
        #expect(throws: WireError.truncated("user")) { try Request.decode(huge) }
    }

    @Test func signedMessages() throws {
        let bytes = try vectors.hex("request", "bytes_hex")
        let digest = Messages.requestDigest(bytes)
        let request = try Request.decode(bytes)
        let reason = try vectors.string("messages", "deny_reason")
        #expect(Messages.hostRequest(bytes) == (try vectors.hex("messages", "host_request_hex")))
        #expect(Messages.approve(digest: digest) == (try vectors.hex("messages", "approve_hex")))
        #expect(Messages.deny(digest: digest, reason: Data(reason.utf8)) == (try vectors.hex("messages", "deny_hex")))
        #expect(Messages.deny(digest: digest, reason: Data()) == (try vectors.hex("messages", "deny_empty_hex")))
        #expect(Messages.envelopeInfo(pairingID: request.pairingID) == (try vectors.hex("messages", "envelope_info_hex")))
        let confirm = Messages.pairConfirm(
            pairingID: request.pairingID,
            phoneSignPub: try vectors.b64("pairing", "phone_sign_pub_b64"),
            phoneKemPub: try vectors.b64("pairing", "phone_kem_pub_b64")
        )
        #expect(confirm == (try vectors.hex("messages", "pair_confirm_hex")))
        let ack = Messages.pairAck(
            pairingID: request.pairingID,
            phoneSignPub: try vectors.b64("pairing", "phone_sign_pub_b64"),
            phoneKemPub: try vectors.b64("pairing", "phone_kem_pub_b64"),
            nonce: try vectors.b64("pairing", "ack_nonce_b64")
        )
        #expect(ack == (try vectors.hex("messages", "pair_ack_hex")))
        #expect(ack != confirm)
    }

    @Test func signatures() throws {
        let hostPub = try vectors.b64("signatures", "host_pub_b64")
        let phonePub = try vectors.b64("signatures", "phone_sign_pub_b64")
        let hostRequest = try vectors.hex("messages", "host_request_hex")
        let hostSig = try vectors.b64("signatures", "host_request_sig_b64")
        #expect(Crypto.verify(publicKey: hostPub, message: hostRequest, signature: hostSig))
        #expect(!Crypto.verify(publicKey: phonePub, message: hostRequest, signature: hostSig))
        #expect(!Crypto.verify(publicKey: hostPub, message: hostRequest + [0], signature: hostSig))
        #expect(!Crypto.verify(publicKey: hostPub, message: hostRequest, signature: hostSig.dropLast()))
        #expect(!Crypto.verify(publicKey: Data(count: 65), message: hostRequest, signature: hostSig))

        let confirm = try vectors.hex("messages", "pair_confirm_hex")
        let confirmSig = try vectors.b64("signatures", "pair_confirm_sig_b64")
        #expect(Crypto.verify(publicKey: hostPub, message: confirm, signature: confirmSig))
        let ack = try vectors.hex("messages", "pair_ack_hex")
        let ackSig = try vectors.b64("signatures", "pair_ack_sig_b64")
        #expect(Crypto.verify(publicKey: hostPub, message: ack, signature: ackSig))
        // An acknowledgement is not a confirmation, and the other way round.
        #expect(!Crypto.verify(publicKey: hostPub, message: confirm, signature: ackSig))
        #expect(!Crypto.verify(publicKey: hostPub, message: ack, signature: confirmSig))

        let approve = try vectors.hex("messages", "approve_hex")
        let deny = try vectors.hex("messages", "deny_hex")
        let approveSig = try vectors.b64("signatures", "approve_sig_b64")
        let denySig = try vectors.b64("signatures", "deny_sig_b64")
        #expect(Crypto.verify(publicKey: phonePub, message: approve, signature: approveSig))
        #expect(Crypto.verify(publicKey: phonePub, message: deny, signature: denySig))
        // A denial is not an approval, and the other way round.
        #expect(!Crypto.verify(publicKey: phonePub, message: approve, signature: denySig))
        #expect(!Crypto.verify(publicKey: phonePub, message: deny, signature: approveSig))
    }

    @Test func pairingLinkAndTranscript() throws {
        let link = try vectors.string("pairing", "link")
        let offer = try PairingOffer(link: link)
        #expect(offer.relayURL == (try vectors.string("pairing", "relay_url")))
        #expect(offer.pairingID == (try vectors.hex("pairing", "pairing_id_hex")))
        #expect(offer.hostPub == (try vectors.b64("pairing", "host_pub_b64")))
        #expect(offer.secret == (try vectors.b64("pairing", "secret_b64")))
        #expect(offer.hostName == (try vectors.string("pairing", "host_name")))
        #expect(offer.link == link)
        #expect(try PairingOffer(link: "  " + link + "\n") == offer)

        for invalid in try #require(try vectors.section("pairing")["invalid_links"] as? [String]) {
            #expect(throws: PairingOffer.ParseError.self, "accepted \(invalid)") { try PairingOffer(link: invalid) }
        }
        #expect(throws: PairingOffer.ParseError.self) { try PairingOffer(link: link + "%") }
        #expect(throws: PairingOffer.ParseError.self) { try PairingOffer(link: link + "%zz") }
        #expect(throws: PairingOffer.ParseError.self) { try PairingOffer(link: link.replacingOccurrences(of: "&s=", with: "&t=")) }

        let parties = Crypto.Parties(
            pairingID: offer.pairingID,
            hostPub: offer.hostPub,
            phoneSignPub: try vectors.b64("pairing", "phone_sign_pub_b64"),
            phoneKemPub: try vectors.b64("pairing", "phone_kem_pub_b64")
        )
        let phoneName = try vectors.string("pairing", "phone_name")
        #expect(Crypto.claimMAC(secret: offer.secret, parties: parties, phoneName: phoneName)
            == (try vectors.b64("pairing", "claim_mac_b64")))
        let nonce = try vectors.b64("pairing", "ack_nonce_b64")
        #expect(nonce.count == Proto.ackNonceLength)
        #expect(Crypto.confirmationCode(secret: offer.secret, parties: parties, ackNonce: nonce)
            == (try vectors.string("pairing", "confirmation_code")))
    }

    @Test func envelopeOpens() throws {
        let kem = try P256.KeyAgreement.PrivateKey(rawRepresentation: try vectors.hex("envelope", "kem_private_hex"))
        #expect(kem.publicKey.x963Representation == (try vectors.b64("envelope", "kem_public_b64")))
        let envelope = try vectors.b64("envelope", "envelope_b64")
        let pairingID = try vectors.hex("pairing", "pairing_id_hex")
        let (hostSig, request) = try Crypto.openEnvelope(envelope, kemPrivate: kem, pairingID: pairingID)
        #expect(hostSig + request == (try vectors.hex("envelope", "plaintext_hex")))
        #expect(request == (try vectors.hex("request", "bytes_hex")))

        // Wrong pairing, wrong key, and tampering all fail.
        #expect(throws: Crypto.EnvelopeError.self) {
            try Crypto.openEnvelope(envelope, kemPrivate: kem, pairingID: Data(repeating: 0xb2, count: 16))
        }
        #expect(throws: Crypto.EnvelopeError.self) {
            try Crypto.openEnvelope(envelope, kemPrivate: P256.KeyAgreement.PrivateKey(), pairingID: pairingID)
        }
        for index in [0, 40, 65, envelope.count - 1] {
            var tampered = envelope
            tampered[index] ^= 1
            #expect(throws: Crypto.EnvelopeError.self, "accepted a flip at byte \(index)") {
                try Crypto.openEnvelope(tampered, kemPrivate: kem, pairingID: pairingID)
            }
        }
        #expect(throws: Crypto.EnvelopeError.self) {
            try Crypto.openEnvelope(envelope.prefix(64), kemPrivate: kem, pairingID: pairingID)
        }
        // And our own sealing, used by tests, interoperates with our opening.
        let sealed = try Crypto.sealEnvelope(hostSignature: hostSig, request: request, kemPublic: kem.publicKey, pairingID: pairingID)
        #expect(try Crypto.openEnvelope(sealed, kemPrivate: kem, pairingID: pairingID).request == request)
    }

    @Test func escaping() throws {
        let cases = try #require(vectors.root["escape"] as? [[String]])
        #expect(cases.count >= 7)
        for pair in cases {
            let escaped = EscapedText(try Codec.hexDecode(pair[0]))
            #expect(escaped.plain == pair[1], "input \(pair[0])")
        }
        // Escapes are identifiable, and ordinary text is not marked.
        let mixed = EscapedText(Data("ok\u{202e}x".utf8) + [0xff])
        #expect(mixed.runs == [
            .init(text: "ok", isEscape: false), .init(text: "\\u{202e}", isEscape: true),
            .init(text: "x", isEscape: false), .init(text: "\\xff", isEscape: true),
        ])
        #expect(!EscapedText("plain").hasEscapes)
    }

    @Test func environmentRisk() throws {
        let section = try vectors.section("env_risk")
        for name in try #require(section["risky"] as? [String]) {
            #expect(EnvRisk.isRisky(Data(name.utf8)), "\(name) should be flagged")
        }
        for name in try #require(section["safe"] as? [String]) {
            #expect(!EnvRisk.isRisky(Data(name.utf8)), "\(name) should not be flagged")
        }
        #expect(EnvRisk.isRisky(Data([0xff, 0xfe])))
    }

    /// The reference's own signatures drive the pairing logic end to end.
    @Test func pairingProgressFollowsTheReferenceSignatures() throws {
        let offer = try PairingOffer(link: try vectors.string("pairing", "link"))
        var pairing = try Pairing(
            offer: offer,
            signPub: try vectors.b64("pairing", "phone_sign_pub_b64"),
            kemPub: try vectors.b64("pairing", "phone_kem_pub_b64"),
            hardwareBacked: false
        )
        #expect(pairing.code == nil)
        let ack = API.Ack(
            nonce: try vectors.string("pairing", "ack_nonce_b64"),
            hostSig: try vectors.string("signatures", "pair_ack_sig_b64")
        )
        let confirm = try vectors.string("signatures", "pair_confirm_sig_b64")
        let code = try vectors.string("pairing", "confirmation_code")
        // The reference's signature with any other nonce is refused.
        var renonced = ack
        renonced.nonce = Codec.b64Encode(Data(repeating: 0x4f, count: 16))
        #expect(throws: PairingError.anotherPhoneWasAccepted) {
            try pairing.observe(API.PairingStatus(state: .acknowledged, ack: renonced, hostSig: nil))
        }
        #expect(try pairing.observe(API.PairingStatus(state: .acknowledged, ack: ack, hostSig: nil)) == .showCode(code))
        #expect(try pairing.observe(API.PairingStatus(state: .active, ack: ack, hostSig: confirm)) == .active)
        // The status as the relay sends it decodes with the new field.
        let json = Data(#"{"state":"acknowledged","ack":{"nonce":"\#(ack.nonce)","host_sig":"\#(ack.hostSig)"}}"#.utf8)
        #expect(try JSONDecoder().decode(API.PairingStatus.self, from: json)
            == API.PairingStatus(state: .acknowledged, ack: ack, hostSig: nil))
        #expect(try JSONDecoder().decode(API.PairingStatus.self, from: Data(#"{"state":"claimed"}"#.utf8))
            == API.PairingStatus(state: .claimed, ack: nil, hostSig: nil))
    }

    @Test func everySectionIsCovered() {
        // If the generator grows a section, a test must be added for it.
        let known: Set = ["about", "codec", "request", "messages", "signatures", "pairing", "envelope", "escape", "env_risk"]
        #expect(Set(vectors.root.keys) == known)
    }
}
